"""Utility functions para mini repo fixture."""

def add(a: int, b: int) -> int:
    """Suma dos números."""
    return a + b


def multiply(x: float, y: float) -> float:
    """Multiplica dos números."""
    return x * y


def greet(name: str) -> str:
    """Retorna un saludo personalizado."""
    return f"Hola, {name}!"
